import { BaseClient } from './base.js';
export class RssAPI extends BaseClient {
    async addRss(options) {
        return this.request('/rss/addrss', {
            method: 'POST',
            body: JSON.stringify(options),
        });
    }
    async modifyRss(feedId, options) {
        return this.request('/rss/modifyrss', {
            method: 'POST',
            body: JSON.stringify({
                feed_id: feedId,
                ...options,
            }),
        });
    }
    async controlRss(feedId, operation) {
        return this.request('/rss/controlrss', {
            method: 'POST',
            body: JSON.stringify({
                feed_id: feedId,
                operation,
            }),
        });
    }
}
